ALTER TABLE wl_eeo_answers ADD COLUMN veteran_classes TEXT;
ALTER TABLE wl_eeo_answers ADD COLUMN disability TEXT CHECK (disability IS NULL OR disability IN ('yes', 'no', 'declined'));
