-- An erasure request names a worker or an applicant who was not hired. The request table has no inbound keys.
DROP INDEX wl_erasure_one_open;
CREATE TABLE wl_erasure_requests_next (
  id TEXT PRIMARY KEY,
  person_id TEXT REFERENCES wl_people(id),
  application_id TEXT,
  source TEXT NOT NULL CHECK (source IN ('own_request', 'retention_expiry', 'counsel', 'other')),
  received_on TEXT NOT NULL CHECK (length(received_on) = 10),
  requested_by TEXT NOT NULL REFERENCES wl_members(id),
  requested_at INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'confirmed', 'withdrawn')),
  confirmed_digest TEXT,
  confirmed_by TEXT REFERENCES wl_members(id),
  confirmed_at INTEGER,
  receipt_id TEXT,
  CHECK ((person_id IS NULL) <> (application_id IS NULL))
);
INSERT INTO wl_erasure_requests_next (id, person_id, source, received_on, requested_by, requested_at, status, confirmed_digest, confirmed_by, confirmed_at, receipt_id)
  SELECT id, person_id, source, received_on, requested_by, requested_at, status, confirmed_digest, confirmed_by, confirmed_at, receipt_id FROM wl_erasure_requests;
DROP TABLE wl_erasure_requests;
ALTER TABLE wl_erasure_requests_next RENAME TO wl_erasure_requests;
CREATE UNIQUE INDEX wl_erasure_one_open ON wl_erasure_requests(person_id) WHERE person_id IS NOT NULL AND status IN ('open', 'confirmed');
CREATE UNIQUE INDEX wl_erasure_one_open_applicant ON wl_erasure_requests(application_id) WHERE application_id IS NOT NULL AND status IN ('open', 'confirmed');

-- Erased source identities are HMAC blind indexes, never plain source keys.
-- The private key travels only in owner installation archives, never employee exports.
CREATE TABLE wl_retention_import_secret (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  secret TEXT NOT NULL
);
CREATE TABLE wl_erased_import_keys (
  digest TEXT PRIMARY KEY,
  receipt_id TEXT NOT NULL
);

CREATE TABLE wl_import_erasure_fences (
  job_id TEXT PRIMARY KEY,
  receipt_id TEXT NOT NULL
);

-- Preboarding requests deliberately have no identity FK: erasure replaces the
-- reference with a random stub while removing both live packet and identity.
DROP INDEX wl_erasure_one_open;
DROP INDEX wl_erasure_one_open_applicant;
CREATE TABLE wl_erasure_requests_next (
  id TEXT PRIMARY KEY,
  person_id TEXT REFERENCES wl_people(id),
  application_id TEXT,
  preboarding_id TEXT,
  source TEXT NOT NULL CHECK (source IN ('own_request', 'retention_expiry', 'counsel', 'other')),
  received_on TEXT NOT NULL CHECK (length(received_on) = 10),
  requested_by TEXT NOT NULL REFERENCES wl_members(id),
  requested_at INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'confirmed', 'withdrawn')),
  confirmed_digest TEXT,
  confirmed_by TEXT REFERENCES wl_members(id),
  confirmed_at INTEGER,
  receipt_id TEXT,
  CHECK ((person_id IS NOT NULL) + (application_id IS NOT NULL) + (preboarding_id IS NOT NULL) = 1)
);
INSERT INTO wl_erasure_requests_next
  (id, person_id, application_id, source, received_on, requested_by, requested_at,
   status, confirmed_digest, confirmed_by, confirmed_at, receipt_id)
SELECT id, person_id, application_id, source, received_on, requested_by, requested_at,
  status, confirmed_digest, confirmed_by, confirmed_at, receipt_id FROM wl_erasure_requests;
DROP TABLE wl_erasure_requests;
ALTER TABLE wl_erasure_requests_next RENAME TO wl_erasure_requests;
CREATE UNIQUE INDEX wl_erasure_one_open ON wl_erasure_requests(person_id) WHERE person_id IS NOT NULL AND status IN ('open', 'confirmed');
CREATE UNIQUE INDEX wl_erasure_one_open_applicant ON wl_erasure_requests(application_id) WHERE application_id IS NOT NULL AND status IN ('open', 'confirmed');
CREATE UNIQUE INDEX wl_erasure_one_open_preboarding ON wl_erasure_requests(preboarding_id) WHERE preboarding_id IS NOT NULL AND status IN ('open', 'confirmed');

-- Explicit compensation approval; preserve every existing grant and seed no new right.
DROP VIEW wl_effective_permissions;
CREATE TABLE wl_permissions_compensation (
  member_id TEXT NOT NULL REFERENCES wl_members(id),
  permission TEXT NOT NULL CHECK (permission IN ('people.manage', 'people.private', 'pay.read', 'leave.manage', 'payroll.handoff', 'documents.private', 'reports.read', 'it.tasks', 'audit.read', 'eeo.read', 'eeo.individual', 'compensation.approve')),
  granted_by TEXT NOT NULL,
  granted_at INTEGER NOT NULL,
  PRIMARY KEY (member_id, permission)
);
INSERT INTO wl_permissions_compensation (member_id, permission, granted_by, granted_at) SELECT member_id, permission, granted_by, granted_at FROM wl_permissions;
DROP TABLE wl_permissions;
ALTER TABLE wl_permissions_compensation RENAME TO wl_permissions;
CREATE VIEW wl_effective_permissions AS
 SELECT member_id,permission FROM wl_permissions
 UNION
 SELECT a.member_id,p.permission FROM wl_member_levels a
 JOIN wl_levels l ON l.id=a.level_id AND l.scope_kind='everyone'
 JOIN wl_level_permissions p ON p.level_id=a.level_id
 JOIN wl_members m ON m.id=a.member_id AND m.status='active';

-- Legal names keep approval by default; no rows are seeded and no old authority widens.
CREATE TABLE wl_level_self_fields_names (
 level_id TEXT NOT NULL REFERENCES wl_levels(id),
 field TEXT NOT NULL CHECK(field IN ('legalName','preferredName','personal_email','phone','address','date_of_birth','emergency_contact')),
 mode TEXT NOT NULL CHECK(mode IN ('view','approval','edit')),
 PRIMARY KEY(level_id,field)
);
INSERT INTO wl_level_self_fields_names SELECT * FROM wl_level_self_fields;
DROP TABLE wl_level_self_fields;
ALTER TABLE wl_level_self_fields_names RENAME TO wl_level_self_fields;

-- Explicit access delegation; preserve all existing grants and seed no new authority.
DROP VIEW wl_effective_permissions;
CREATE TABLE wl_permissions_delegation (
  member_id TEXT NOT NULL REFERENCES wl_members(id),
  permission TEXT NOT NULL CHECK (permission IN ('people.manage', 'people.private', 'pay.read', 'leave.manage', 'payroll.handoff', 'documents.private', 'reports.read', 'it.tasks', 'audit.read', 'eeo.read', 'eeo.individual', 'compensation.approve', 'access.admin')),
  granted_by TEXT NOT NULL,
  granted_at INTEGER NOT NULL,
  PRIMARY KEY (member_id, permission)
);
INSERT INTO wl_permissions_delegation (member_id, permission, granted_by, granted_at) SELECT member_id, permission, granted_by, granted_at FROM wl_permissions;
DROP TABLE wl_permissions;
ALTER TABLE wl_permissions_delegation RENAME TO wl_permissions;
CREATE VIEW wl_effective_permissions AS
 SELECT member_id,permission FROM wl_permissions
 UNION
 SELECT a.member_id,p.permission FROM wl_member_levels a
 JOIN wl_levels l ON l.id=a.level_id AND l.scope_kind='everyone'
 JOIN wl_level_permissions p ON p.level_id=a.level_id
 JOIN wl_members m ON m.id=a.member_id AND m.status='active';

ALTER TABLE wl_level_reviews ADD COLUMN needs_approval INTEGER NOT NULL DEFAULT 0 CHECK(needs_approval IN (0,1));

